    /**
     * Selects a collection of ClPrestamo objects pre-filled with their Regional objects.
     * @param      Criteria  $criteria
     * @param      PropelPDO $con
     * @param      String    $join_behavior the type of joins to use, defaults to Criteria::LEFT_JOIN
     * @return array           Array of ClPrestamo objects.
     * @throws PropelException Any exceptions caught during processing will be
     *		 rethrown wrapped into a PropelException.
     */
    public static function doSelectJoinRegional(Criteria $criteria, $con = null, $join_behavior = Criteria::LEFT_JOIN)
    {
        $criteria = clone $criteria;

        // Set the correct dbName if it has not been overridden
        if ($criteria->getDbName() == Propel::getDefaultDB()) {
            $criteria->setDbName(ClPrestamoPeer::DATABASE_NAME);
        }

        ClPrestamoPeer::addSelectColumns($criteria);
        $startcol = ClPrestamoPeer::NUM_HYDRATE_COLUMNS;
        RegionalPeer::addSelectColumns($criteria);

        $criteria->addJoin(ClPrestamoPeer::REGIONAL_ID, RegionalPeer::REGIONAL_ID, $join_behavior);

        // symfony_behaviors behavior
        foreach (sfMixer::getCallables(self::getMixerPreSelectHook(__FUNCTION__)) as $sf_hook)
        {
          call_user_func($sf_hook, 'BaseClPrestamoPeer', $criteria, $con);
        }

        $stmt = BasePeer::doSelect($criteria, $con);
        $results = array();

        while ($row = $stmt->fetch(PDO::FETCH_NUM)) {
            $key1 = ClPrestamoPeer::getPrimaryKeyHashFromRow($row, 0);
            if (null !== ($obj1 = ClPrestamoPeer::getInstanceFromPool($key1))) {
                // We no longer rehydrate the object, since this can cause data loss.
                // See http://www.propelorm.org/ticket/509
                // $obj1->hydrate($row, 0, true); // rehydrate
            } else {

                $cls = ClPrestamoPeer::getOMClass();

                $obj1 = new $cls();
                $obj1->hydrate($row);
                ClPrestamoPeer::addInstanceToPool($obj1, $key1);
            } // if $obj1 already loaded

            $key2 = RegionalPeer::getPrimaryKeyHashFromRow($row, $startcol);
            if ($key2 !== null) {
                $obj2 = RegionalPeer::getInstanceFromPool($key2);
                if (!$obj2) {

                    $cls = RegionalPeer::getOMClass();

                    $obj2 = new $cls();
                    $obj2->hydrate($row, $startcol);
                    RegionalPeer::addInstanceToPool($obj2, $key2);
                } // if obj2 already loaded

                // Add the $obj1 (ClPrestamo) to $obj2 (Regional)
                $obj2->addClPrestamo($obj1);

            } // if joined row was not null

            $results[] = $obj1;
        }
        $stmt->closeCursor();

        return $results;
    }


