        ClEstadoPrestamoPeer::addSelectColumns($criteria);
        $startcol4 = $startcol3 + ClEstadoPrestamoPeer::NUM_HYDRATE_COLUMNS;

        PeriodoPeer::addSelectColumns($criteria);
        $startcol5 = $startcol4 + PeriodoPeer::NUM_HYDRATE_COLUMNS;

        $criteria->addJoin(ClPrestamoPeer::USUARIO_ID, UsuarioPeer::USUARIO_ID, $join_behavior);

