                } // if $obj4 already loaded

                // Add the $obj1 (ClPrestamo) to the collection in $obj4 (Periodo)
                $obj4->addClPrestamo($obj1);

            } // if joined row is not null

            $results[] = $obj1;
        }
        $stmt->closeCursor();

        return $results;
    }


